import { z } from "zod";

export const RootItemSchema = z.object({
  a: z.number().int().optional(),
  b: z.array(z.unknown()).optional(),
});
export type RootItem = z.infer<typeof RootItemSchema>;

export const RootSchema = z.array(z.union([z.boolean(), z.number(), z.string(), z.array(z.union([z.number().int(), z.array(z.unknown()), z.record(z.string(), z.unknown())])), RootItemSchema]).nullable());
export type Root = z.infer<typeof RootSchema>;

